// Deliberately allowlisted: no profile name, storage dump, URL query or credentials.
export function debugReport(state,engines,camera,controls,errors=[]){
 const point=v=>v?[v.x,v.y,v.z].map(n=>Math.round(n*100)/100):null;
 return JSON.stringify({version:101,generatedAt:new Date().toISOString(),clock:state.minute,speed:state.speed,speedMode:state.speedMode,paused:state.paused,citySeed:state.citySeed,selected:state.selected,viewport:[innerWidth,innerHeight,devicePixelRatio],camera:point(camera.position),target:point(controls.target),staff:{free:state.freeStaff,present:state.roster.filter(p=>p.present).length},volunteers:(state.recallRequests||[]).map(r=>({personId:r.personId,status:r.status,phase:r.phase,activity:r.activity,at:r.at,physicalReady:r.physicalReady})),calls:state.calls.filter(c=>c.status!=='closed').map(c=>({id:c.id,type:c.type,scene:c.scene,status:c.status,target:c.target,accessTarget:c.accessTarget,actionPoint:c.actionPoint,progress:c.progress,fireContained:c.fireContained,reconComplete:c.reconComplete,accessClosed:c.accessClosed,victims:c.victimCount,siteCompletedAt:c.siteCompletedAt})),vehicles:engines.map(e=>({id:e.id,kind:e.kind,base:e.localVolunteer?'CIS Sud':e.external?e.base:'CIS Centre',status:e.status,call:e.call,position:point(e.model.position),yaw:e.model.rotation.y,home:e.home,crew:e.crew,localCrew:e.localCrew?.map(p=>({phase:p.phase,activity:p.activity,departAt:p.departAt,stationAt:p.stationAt,changedAt:p.changedAt,arrivalAt:p.arrivalAt})),water:e.water,capacity:e.capacity,nozzles:e.nozzles,flow:e.flow,parking:e.parking,segment:e.segment,path:e.path?.slice(Math.max(0,(e.segment||0)-2)),trafficWaiting:e.trafficWaiting,controlWaiting:e.controlWaiting,departAt:e.departAt,workActive:e.workActive})),errors:errors.slice(-15)},null,2);
}
export function installDebug({state,engines,camera,controls,modal}){
 const errors=[];globalThis.addEventListener?.('error',e=>{errors.push({message:e.message,line:e.lineno,column:e.colno});if(errors.length>15)errors.shift();});globalThis.addEventListener?.('unhandledrejection',e=>{errors.push({message:String(e.reason?.message||e.reason)});if(errors.length>15)errors.shift();});
 document.getElementById('debug').onclick=()=>{
  const report=debugReport(state,engines,camera,controls,errors);
  modal('<h2>Diagnostic du jeu</h2><p>Copie ce rapport avec ta capture et une description du problème.</p><textarea id="debugReport" readonly aria-label="Rapport de diagnostic" style="width:100%;height:45vh"></textarea><p id="debugStatus" role="status"></p><div class="actions"><button id="copyDebug">Copier le rapport</button><button data-close>Fermer</button></div>');
  const area=document.getElementById('debugReport');area.value=report;
  document.getElementById('copyDebug').onclick=async()=>{const status=document.getElementById('debugStatus');try{await navigator.clipboard.writeText(report);status.textContent='Rapport copié.';}catch{area.focus();area.select();status.textContent='Rapport sélectionné : utilise Ctrl+C ou ⌘C pour le copier.';}};
 };
}
